    printf("Testing column index out of bounds (col = 50)...\n");
    char* result3 = get_cell_data(spreadsheet, 0, 50);

    // 测试用例4: 列索引超出下界
    printf("Testing column index out of bounds (col = -1)...\n");
    char* result4 = get_cell_data(spreadsheet, 0, -1);

    // 测试用例5: 同时超出行列边界
    printf("Testing both row and column indices out of bounds (row = 1001, col = 51)...\n");
    char* result5 = get_cell_data(spreadsheet, 1001, 51);

    // 测试用例6: 大数值越界
    printf("Testing large out of bounds indices (row = 2000, col = 100)...\n");
    char* result6 = get_cell_data(spreadsheet, 2000, 100);

    // 清理测试数据
    for (int i = 0; i < 1000; i++) {
        for (int j = 0; j < 50; j++) {
            free(spreadsheet[i][j]);
        }
    }

    // 如果程序没有崩溃，测试完成
    printf("Security tests completed. Check for sanitizer reports.\n");

    return 0;
}

